"""Defines PluginTestService."""

from __future__ import annotations

import asyncio.subprocess
import json
import json.decoder
import sys
import typing as t
from abc import ABC, abstractmethod

import structlog

from meltano.core.plugin.base import PluginType
from meltano.core.plugin.error import PluginNotSupportedError

if sys.version_info >= (3, 12):
    from typing import override  # noqa: ICN003
else:
    from typing_extensions import override

if t.TYPE_CHECKING:
    from meltano.core.plugin_invoker import PluginInvoker

logger = structlog.stdlib.get_logger(__name__)


class PluginTestServiceFactory:
    """Factory class to resolve a plugin test service."""

    def __init__(self, plugin_invoker: PluginInvoker):
        """Construct a PluginTestServiceFactory instance.

        Args:
            plugin_invoker: The invocation instance of the plugin to test.
        """
        self.plugin_invoker = plugin_invoker

    def get_test_service(self):  # noqa: ANN201
        """Resolve a test service instance for a plugin type.

        Returns:
            The test service instance.

        Raises:
            PluginNotSupportedError: If the plugin type is not supported for testing.
        """
        test_services = {
            PluginType.EXTRACTORS: ExtractorTestService,
            PluginType.LOADERS: LoaderTestService,
        }

        try:
            return test_services[self.plugin_invoker.plugin.type](self.plugin_invoker)
        except KeyError as err:
            raise PluginNotSupportedError(self.plugin_invoker.plugin) from err


class PluginTestService(ABC):
    """Abstract base class for plugin test operations."""

    def __init__(self, plugin_invoker: PluginInvoker):
        """Construct a PluginTestService instance.

        Args:
            plugin_invoker: The invocation instance of the plugin to test
        """
        self.plugin_invoker = plugin_invoker

    @abstractmethod
    async def validate(self, **kwargs: t.Any) -> tuple[bool, str | None]:
        """Abstract method to validate plugin configuration."""


class ExtractorTestService(PluginTestService):
    """Handle extractor test operations."""

    @override
    async def validate(self, **kwargs: t.Any) -> tuple[bool, str | None]:
        """Validate extractor configuration.

        Returns:
            The validation result and supporting context message (if applicable).
        """
        process = None

        try:
            process = await self.plugin_invoker.invoke_async(
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
                **kwargs,
            )
        except Exception as exc:  # noqa: BLE001
            return False, str(exc)

        record_message_received: bool = False
        last_line: str | None = None

        while process.stdout and not process.stdout.at_eof():
            data = await process.stdout.readline()
            line = data.decode("utf-8").strip()
            if line:
                logger.debug(line)
                last_line = line

            try:
                message_type = json.loads(line)["type"]
            except (json.decoder.JSONDecodeError, KeyError):
                continue

            record_message_received = message_type in {"RECORD", "BATCH"}
            if record_message_received:
                process.terminate()
                break

        returncode = await process.wait()
        logger.debug("Process return code: %s", returncode)

        user_message = (
            "No RECORD or BATCH message received. "
            "Verify that at least one stream is selected using "
            f"'meltano select {self.plugin_invoker.plugin.name} --list'."
        )

        return (record_message_received, last_line if returncode else user_message)


class LoaderTestService(PluginTestService):
    """Handle loader test operations."""

    @override
    async def validate(self, **kwargs: t.Any) -> tuple[bool, str | None]:
        """Validate loader configuration by sending test Singer messages.

        Returns:
            The validation result and supporting context message (if applicable).
        """
        # Warn users about potential side effects
        logger.warning(
            "Testing a loader will write test data to your target system. "
            "This test will create a table/collection called 'meltano_test_stream'. "
            "You may need to manually clean up this test data after the test "
            "completes.",
        )

        try:
            process = await self.plugin_invoker.invoke_async(
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
                **kwargs,
            )
        except Exception as exc:  # noqa: BLE001
            return False, str(exc)

        # Generate test Singer messages
        test_stream_name = "meltano_test_stream"
        test_messages = self._generate_test_messages(test_stream_name)

        assert process.stdin is not None  # noqa: S101

        try:
            # Send test messages to the loader
            for message in test_messages:
                process.stdin.write((message + "\n").encode("utf-8"))
                await process.stdin.drain()

            # Close stdin to signal end of input
            process.stdin.close()
            await process.stdin.wait_closed()

            # Read output
            last_line: str | None = None
            error_occurred = False

            while process.stdout and not process.stdout.at_eof():
                data = await process.stdout.readline()
                if line := data.decode("utf-8").strip():
                    logger.debug(line)
                    last_line = line
                    # Check for error indicators
                    if "error" in line.lower() or "exception" in line.lower():
                        error_occurred = True

            returncode = await process.wait()
            logger.debug("Process return code: %s", returncode)

            if returncode == 0 and not error_occurred:
                logger.info(
                    "Test data was written to your target system. "
                    "You may want to clean up the 'meltano_test_stream' "
                    "table/collection.",
                )
                return (
                    True,
                    (
                        "Successfully processed test data for loader "
                        f"'{self.plugin_invoker.plugin.name}'."
                    ),
                )
            return (  # noqa: TRY300
                False,
                last_line or "Loader failed to process test data.",
            )

        except Exception as exc:  # noqa: BLE001
            return False, str(exc)
        finally:
            process.terminate()
            await process.wait()

    def _generate_test_messages(self, stream_name: str) -> list[str]:
        """Generate test Singer messages for loader validation.

        Args:
            stream_name: Name of the test stream.

        Returns:
            List of Singer message strings (SCHEMA, RECORD, STATE, optionally
                ACTIVATE_VERSION).
        """
        messages = []

        # SCHEMA message
        schema_message = {
            "type": "SCHEMA",
            "stream": stream_name,
            "schema": {
                "type": "object",
                "properties": {
                    "id": {"type": "integer"},
                    "name": {"type": "string"},
                    "created_at": {"type": "string", "format": "date-time"},
                },
            },
            "key_properties": ["id"],
        }
        messages.append(json.dumps(schema_message))

        # RECORD message
        record_message = {
            "type": "RECORD",
            "stream": stream_name,
            "record": {
                "id": 1,
                "name": "Meltano Test Record",
                "created_at": "2025-09-29T00:00:00Z",
            },
        }
        messages.append(json.dumps(record_message))

        # STATE message
        state_message = {
            "type": "STATE",
            "value": {
                "bookmarks": {
                    stream_name: {
                        "last_record": 1,
                    },
                },
            },
        }
        messages.append(json.dumps(state_message))

        # ACTIVATE_VERSION message (if loader has activate-version capability)
        if "activate-version" in self.plugin_invoker.capabilities:
            activate_version_message = {
                "type": "ACTIVATE_VERSION",
                "stream": stream_name,
                "version": 1,
            }
            messages.append(json.dumps(activate_version_message))

        return messages

from __future__ import annotations

import base64
import json
import platform
import stat
import typing as t
from datetime import datetime, timedelta
from datetime import timezone as tz
from pathlib import Path

import pytest

from meltano.core.cloud.credentials import Credentials, CredentialsStore


def make_id_token(claims: dict[str, t.Any]) -> str:
    """Build an unsigned JWT with the given claims."""
    payload = base64.urlsafe_b64encode(json.dumps(claims).encode()).decode().rstrip("=")
    return f"header.{payload}.signature"


class TestCredentials:
    def test_from_token_response(self) -> None:
        credentials = Credentials.from_token_response(
            {
                "access_token": "at",
                "refresh_token": "rt",
                "id_token": "it",
                "token_type": "Bearer",
                "expires_in": 86400,
                "scope": "openid",
            },
        )
        assert credentials.access_token =<REDACTED> "at"
        assert credentials.refresh_token =<REDACTED> "rt"
        assert credentials.id_token =<REDACTED> "it"
        assert credentials.scope == "openid"
        assert credentials.expires_at is not None
        assert not credentials.is_expired

    def test_from_token_response_keeps_previous_refresh_token(self) -> None:
        credentials = Credentials.from_token_response(
            {"access_token": "at", "expires_in": 60},
            refresh_token="<REDACTED>",
        )
        assert credentials.refresh_token =<REDACTED> "previous"

    def test_round_trip(self) -> None:
        expires_at = datetime.now(tz=tz.utc) + timedelta(hours=1)
        credentials = Credentials(
            access_token="<REDACTED>",
            refresh_token="<REDACTED>",
            id_token="<REDACTED>",
            expires_at=expires_at,
            scope="openid",
        )
        assert Credentials.from_dict(credentials.to_dict()) == credentials

    def test_to_dict_omits_empty_values(self) -> None:
        assert Credentials(access_token="<REDACTED>").to_dict() == {
            "access_token": "at",
            "token_type": "Bearer",
        }

    @pytest.mark.parametrize(
        ("delta", "expired"),
        ((timedelta(hours=1), False), (timedelta(seconds=-1), True)),
    )
    def test_is_expired(self, delta: timedelta, expired: bool) -> None:  # noqa: FBT001
        credentials = Credentials(
            access_token="<REDACTED>",
            expires_at=datetime.now(tz=tz.utc) + delta,
        )
        assert credentials.is_expired is expired

    def test_is_expired_within_leeway(self) -> None:
        # A token that expires in 30 seconds is treated as expired, so that it
        # is not rejected between being read and being used.
        credentials = Credentials(
            access_token="<REDACTED>",
            expires_at=datetime.now(tz=tz.utc) + timedelta(seconds=30),
        )
        assert credentials.is_expired

    def test_never_expires_without_expiry(self) -> None:
        assert not Credentials(access_token="<REDACTED>").is_expired

    def test_auth_header(self) -> None:
        credentials = Credentials(access_token="<REDACTED>", token_type="<REDACTED>")
        assert credentials.auth_header == {"Authorization": "Bearer at"}

    def test_claims(self) -> None:
        credentials = Credentials(
            access_token="<REDACTED>",
            id_token=<REDACTED>"email": "user@example.com"}),
        )
        assert credentials.claims["email"] == "user@example.com"

    @pytest.mark.parametrize("id_token", ("", "not-a-jwt", "a.!!!.c"))
    def test_claims_of_invalid_token(self, id_token: <REDACTED> -> None:
        assert Credentials(access_token="<REDACTED>", id_token=<REDACTED> == {}

    def test_with_token_response_keeps_id_token(self) -> None:
        credentials = Credentials(access_token="<REDACTED>", refresh_token="<REDACTED>", id_token="<REDACTED>")
        # Auth0 omits the ID token, and the refresh token unless rotation is
        # enabled, from refresh responses.
        refreshed = credentials.with_token_response(
            {"access_token": "new-at", "expires_in": 60},
        )
        assert refreshed.access_token =<REDACTED> "new-at"
        assert refreshed.refresh_token =<REDACTED> "rt"
        assert refreshed.id_token =<REDACTED> "it"

    def test_with_token_response_accepts_rotated_tokens(self) -> None:
        credentials = Credentials(access_token="<REDACTED>", refresh_token="<REDACTED>", id_token="<REDACTED>")
        refreshed = credentials.with_token_response(
            {"access_token": "new-at", "refresh_token": "new-rt", "id_token": "new-it"},
        )
        assert refreshed.refresh_token =<REDACTED> "new-rt"
        assert refreshed.id_token =<REDACTED> "new-it"


class TestCredentialsStore:
    @pytest.fixture
    def store(self, tmp_path: Path) -> CredentialsStore:
        return CredentialsStore(tmp_path / "cloud" / "credentials.json")

    def test_get_when_missing(self, store: CredentialsStore) -> None:
        assert store.get() is None

    def test_set_and_get(self, store: CredentialsStore) -> None:
        credentials = Credentials(access_token="<REDACTED>", refresh_token="<REDACTED>")
        store.set(credentials)
        assert CredentialsStore(store.path).get() == credentials

    @pytest.mark.skipif(
        platform.system() == "Windows",
        reason="Windows has no POSIX file mode; access is governed by ACLs.",
    )
    def test_set_is_user_readable_only(self, store: CredentialsStore) -> None:
        store.set(Credentials(access_token="<REDACTED>"))
        assert stat.S_IMODE(store.path.stat().st_mode) == 0o600

    def test_set_leaves_no_temporary_file(self, store: CredentialsStore) -> None:
        store.set(Credentials(access_token="<REDACTED>"))
        assert [path.name for path in store.path.parent.iterdir()] == [store.path.name]

    def test_set_replaces_existing_credentials(self, store: CredentialsStore) -> None:
        store.set(Credentials(access_token="<REDACTED>"))
        store.set(Credentials(access_token="<REDACTED>"))
        assert CredentialsStore(store.path).get().access_token =<REDACTED> "second"

    def test_set_cleans_up_the_temporary_file_on_failure(
        self,
        store: CredentialsStore,
        monkeypatch: pytest.MonkeyPatch,
    ) -> None:
        def _fail_replace(self, target):  # noqa: ARG001
            raise OSError

        monkeypatch.setattr(Path, "replace", _fail_replace)

        with pytest.raises(OSError):  # noqa: PT011
            store.set(Credentials(access_token="<REDACTED>"))

        assert list(store.path.parent.iterdir()) == []

    def test_clear(self, store: CredentialsStore) -> None:
        store.set(Credentials(access_token="<REDACTED>"))
        assert store.clear() is True
        assert not store.path.exists()
        assert store.get() is None

    def test_clear_when_missing(self, store: CredentialsStore) -> None:
        assert store.clear() is False

    def test_clear_reports_false_on_other_errors(
        self,
        store: CredentialsStore,
        monkeypatch: pytest.MonkeyPatch,
    ) -> None:
        store.set(Credentials(access_token="<REDACTED>"))

        def _fail_unlink(self):  # noqa: ARG001
            raise PermissionError

        monkeypatch.setattr(Path, "unlink", _fail_unlink)

        assert store.clear() is False

    @pytest.mark.parametrize("content", ("{not json", "{}", '{"access_token": null}'))
    def test_get_malformed(self, store: CredentialsStore, content: str) -> None:
        store.path.parent.mkdir(parents=True)
        store.path.write_text(content)
        assert store.get() is None

from __future__ import annotations

import platform
import typing as t

import pytest

from meltano.core.constants import STATE_ID_COMPONENT_DELIMITER
from meltano.core.environment import (
    Environment,
    EnvironmentNameContainsStateIdDelimiterError,
)
from meltano.core.environment_service import EnvironmentAlreadyExistsError
from meltano.core.utils import NotFound

if t.TYPE_CHECKING:
    from meltano.core.environment_service import EnvironmentService


class TestEnvironmentService:
    @pytest.fixture
    def subject(self, environment_service):
        return environment_service

    @pytest.fixture
    def environment(self, environment_service: EnvironmentService) -> Environment:
        return environment_service.add("test-environment")

    @pytest.mark.order(0)
    def test_add_environment(self, subject: EnvironmentService) -> None:
        count = 10
        environments = [Environment(f"environment_{idx}") for idx in range(count)]
        for environment in environments:
            subject.add_environment(environment)

        # default environments are added to initialised projects
        default_environments = [
            Environment(name) for name in ("dev", "staging", "prod")
        ]
        environments = default_environments + environments

        assert subject.list_environments() == environments

        with pytest.raises(
            EnvironmentAlreadyExistsError,
            match=r"An Environment named 'environment_0' already exists.",
        ):
            subject.add_environment(environments[3])

    @pytest.mark.order(1)
    def test_remove_environment(
        self,
        subject: EnvironmentService,
        environment: Environment,
    ) -> None:
        assert subject.list_environments() == [environment]
        subject.remove(environment.name)
        assert not subject.list_environments()

        with pytest.raises(
            NotFound,
            match="Environment 'i-do-not-exist' was not found",
        ):
            subject.remove("i-do-not-exist")

    @pytest.mark.order(2)
    def test_list_environments(
        self,
        subject: EnvironmentService,
    ) -> None:
        if platform.system() == "Windows":
            pytest.xfail(
